        [TestMethod]
        public void Constructor_Of_Services_Are_Not_Allowed_To_Use_IImmutable_List_Cause_Dependency_Injection_Does_Not_Support_It()
        {
            var ctorsWithImmutableListUsage = FindConstructorsWithImmutableListSignatures().ToImmutableList();

            
            Assert.IsTrue(ctorsWithImmutableListUsage.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_S_00005

Microsoft dependency injection package do not support a set of services with specific list types. 
Out of the box only IEnumerable<T> is supported.
Findings {ctorsWithImmutableListUsage.Count}.{Environment.NewLine}{ctorsWithImmutableListUsage.Flatten(Environment.NewLine)}");

            Assert.IsTrue(ctorsWithImmutableListUsage.IsEmpty(),
                          $"{Environment.NewLine}{Environment.NewLine}Do not use IImmutableList or any other type as IEnumerable<T> for constructors to inject multiple implementations, because it is not supported by the dependency injection.{Environment.NewLine}Total: {ctorsWithImmutableListUsage.Count}{ctorsWithImmutableListUsage.Flatten(Environment.NewLine)}");


            IEnumerable<string> FindConstructorsWithImmutableListSignatures()
            {
                var services = from service in Services
                               from parameter in service.Class.Parameters
                               from type in AllListTypesExceptIEnumerable
                               where parameter.Type.Contains(type)
                               select new
                               {
                                   Class = service.Class,
                               };

                foreach (var serviceWithRegistration in services)
                {
                    yield return $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:       {serviceWithRegistration.Class.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Constructor: 

{serviceWithRegistration.Class.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
";
                }
            }
        }

        [TestMethod]
        public void Services_Should_Use_IEnumerable_To_Inject_A_Set_Of_Services_Cause_Other_List_Types_Are_Not_Supported_By_The_Microsoft_Dependency_Injection()
        {
            var missingRegistrationCalls = FindMissingRegistrationCalls().ToImmutableList();

            Assert.IsTrue(missingRegistrationCalls.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_S_00004

Your service registration in your code have to be called. Otherwise your application will not start. 
Findings {missingRegistrationCalls.Count}.{Environment.NewLine}{missingRegistrationCalls.Flatten(Environment.NewLine)}");

            IEnumerable<string> FindMissingRegistrationCalls()
            {
                var serviceWithRegistrations = from service in Services
                                               where service.Registration is not null
                                               select service;


                var statements = SyntaxTreesToAnalyze.SelectMany(c => c.Classes).SelectMany(c => c.Methods).SelectMany(m => m.Statements).ToImmutableList();

                foreach (var serviceWithRegistration in serviceWithRegistrations)
                {
                    foreach (var registrationMethod in serviceWithRegistration.Registration.Methods)
                    {
                        var missing = !statements.Any(statement => statement.Contains($".{registrationMethod.Name}"));
                        if (missing)
                        {
                            yield return $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Registration: 

{registrationMethod.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:       

services.{registrationMethod.Name}();
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
";
                        }
                    }
                }
            }
        }
